    @Override public void onLoad(){try{if(!Files.isRegularFile(Path.of("ALLOW_DISPOSABLE_RAID_PROBE")))return;Path proof=getDataFolder().toPath();Files.createDirectories(proof);String phase=!Files.exists(proof.resolve("first-passed.txt"))?"first":!Files.exists(proof.resolve("broken-passed.txt"))?"broken":"restart";if(Files.exists(Path.of("TRACE_NATIVE_SQLITE")))SqliteTrace.install(proof.resolve(phase+"-jdbc-trace.txt"),proof.getParent().resolve("NeverLandTownyContracts/server-materials.db"));Path folder=proof.resolve(phase+"-before-plugins");Files.createDirectories(folder);Path base=proof.getParent().resolve("NeverLandTownyContracts/server-materials.db");var text=new StringBuilder();for(String suffix:List.of("","-wal","-shm")){Path f=Path.of(base+suffix);if(Files.exists(f)){byte[] bytes=Files.readAllBytes(f);Files.write(folder.resolve(f.getFileName()),bytes);text.append(f).append(" bytes=").append(bytes.length).append(" sha256=").append(HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(bytes))).append('\n');}}Files.writeString(folder.resolve("files.txt"),text.toString());}catch(Exception error){getLogger().log(java.util.logging.Level.SEVERE,"Startup raw capture failed",error);}}
    void in(Work w){try{w.run();}catch(Throwable e){fail(e);}}
    Player member(UUID uuid,String name){Player base=actor(uuid,name);return(Player)java.lang.reflect.Proxy.newProxyInstance(Player.class.getClassLoader(),new Class<?>[]{Player.class},(proxy,m,args)->m.getName().equals("hasPermission")? !((String)args[0]).endsWith(".admin"):m.invoke(base,args));}
    @Override void setup()throws Exception{
        phase=!Files.exists(proof.resolve("first-passed.txt"))?"first":!Files.exists(proof.resolve("broken-passed.txt"))?"broken":"restart";
        plugin=(NeverLandTownyQuests)Bukkit.getPluginManager().getPlugin("NeverLandTownyQuests");quests=(QuestService)field(plugin,"service");coop=(CooperativeService)field(plugin,"cooperative");menu=(CooperativeMenu)field(plugin,"cooperativeMenu");api=Bukkit.getServicesManager().load(ServerMaterialsApi.class);
        ledger=(ServerMaterials)field(field(Bukkit.getPluginManager().getPlugin("NeverLandTownyContracts"),"publicOrders"),"materials");config=plugin.getDataFolder().toPath().resolve("cooperative.yml");mayor=member(M,"CommonMayor");sponsor=member(S,"CommonHelper");
        for(String shortName:List.of("Citizens","Builds","Contracts","Quests","Control"))check(Bukkit.getPluginManager().isPluginEnabled("NeverLandTowny"+shortName)&&!SuiteState.frozen("NeverLandTowny"+shortName),phase+": "+shortName+" remains enabled and unfrozen");
        denied(()->new CooperativeService.Template("water","No water item","SERVER","joint_water",1,Map.of("WATER",1L)).validateItems(),"actual runtime rejects a valid block with no inventory item");
        check(quests.settings().projects().size()==4,"original four city chains load alongside optional cooperative section");
        if(!phase.equals("first")){town=TownyAPI.getInstance().getTown(T);helper=TownyAPI.getInstance().getTown(U);verifyAuditThenResume();return;}
        town=makeTown(T,M,"CommonCity","CommonMayor",0);helper=makeTown(U,S,"CommonHelperCity","CommonHelper",1);
        var repo=(QuestRepository)field(quests,"repository");var def=quests.settings().projects().get("sanitation");repo.put(T,new CityProject(UUID.randomUUID(),def,def.stages().size(),0,CityProject.Status.COMPLETED));Files.write(proof.resolve("chain.yml"),Files.readAllBytes(plugin.getDataFolder().toPath().resolve("quests-data.yml")));
        check(quests.unlocked(T,"sanitation_reform"),"existing completed city chain unlock retained");denied(()->menu.command(mayor,new String[]{"plan","native_common"}),"ordinary mayor cannot create server-wide project");
        Bukkit.getPluginCommand("townyquests").execute(Bukkit.getConsoleSender(),"townyquests",new String[]{"joint","plan","native_common"});
        await(api.cooperativeProject("native_common"),row->in(()->{check(row.get("state").equals("OPEN")&&row.get("needs").equals(Map.of("OAK_LOG",128L,"GLASS",64L)),"real console command creates immutable material budget through registered API");menu.project(mayor,"native_common",0);later(6,()->{check(windows.get(M).getItem(0).getAmount()==1&&lore(mayor,40).contains("второй выплаты нет"),"native inventory shows budget with safe one-item icons and no extra reward promise");material(id("delivery-unassigned"),T,M,"OAK_LOG",20,"",this::firstDelivery);});}));
    }
    Town makeTown(UUID id,UUID resident,String name,String player,int chunk)throws Exception{var u=TownyUniverse.getInstance();u.newTownInternal(name,id);var t=TownyAPI.getInstance().getTown(id);var r=TownyAPI.getInstance().getResident(resident);if(r==null)r=u.getDataSource().newResident(player,resident);r.setTown(t);t.setMayor(r);r.save();var block=new TownBlock(chunk,0,u.getWorld(world.getName()));u.addTownBlock(block);block.setTown(t);t.setHomeBlock(block);block.save();t.setSpawn(origin);t.save();return t;}
    void material(UUID delivery,UUID city,UUID player,String material,int amount,String project,Work next){
        var d=new ServerMaterials.Delivery(delivery,player,"NativeContributor","native_fixture",material,amount,1000,"COMMON",System.currentTimeMillis());
        CompletionStage<?> job=ledger.prepare(d);if(!project.isEmpty())job=job.thenCompose(v->ledger.cooperativeContext(delivery,player,city.toString(),project));
        job=job.thenCompose(v->ledger.confirm(delivery,"Explicit native inventory-confirmed fixture"));job=job.thenCompose(v->ledger.settled(delivery));await(job,ignored->in(next));
    }
    void firstDelivery()throws Exception{await(api.cooperativeProject("native_common"),row->in(()->{check(((Map<?,?>)row.get("credited")).isEmpty(),"unassigned paid server resources never become retroactive city progress");material(id("delivery-oak"),T,M,"OAK_LOG",160,"native_common",()->await(api.cooperativeProject("native_common"),r->in(()->{check(r.get("credited").equals(Map.of("OAK_LOG",128L)),"confirmed oak receipt reserves exact unmet128; excess remains global stock");await(api.balances(),b->in(()->{check(b.get("OAK_LOG")==52L,"general stock contains unassigned20 plus surplus32");check(!Boolean.TRUE.equals(r.get("funded")),"partial contribution cannot complete project");material(id("delivery-glass"),U,S,"GLASS",64,"native_common",this::funded);}));})));}));}
    void funded()throws Exception{
        await(api.cooperativeReceipts(T,1),rows->in(()->{check(rows.size()==1&&rows.getFirst().get("amount").equals(128L),"city history contains exact one confirmed contribution");await(ledger.confirm(id("delivery-oak"),"Repeated native confirmation"),ignored->in(()->await(api.cooperativeReceipts(T,1),again->in(()->{check(again.size()==1,"duplicate receipt confirmation cannot duplicate city credit");
            denied(()->menu.command(mayor,new String[]{"complete","native_common","confirm","checked city build"}),"ordinary mayor cannot finish server project");
            menu.command(Bukkit.getConsoleSender(),new String[]{"complete","native_common","confirm","Spawn build verified in native fixture"});await(api.cooperativeProject("native_common"),r->in(()->{check(r.get("state").equals("COMPLETED"),"admin verified completion consumes actual reserved budget atomically");await(api.cooperativeUnlocks(T),keys->in(()->{check(keys.contains("joint_native_common"),"original town earns server project result from qualifying contribution");await(api.cooperativeUnlocks(U),other->in(()->{check(other.contains("joint_native_common"),"second contributor town earns same server result once");pollUnlock(40);}));}));}));}))));}));
    }
    void pollUnlock(int left)throws Exception{boolean value=false;try{value=quests.unlocked(T,"joint_native_common");}catch(IllegalStateException pending){}if(!value){if(left<=0)throw new AssertionError("cooperative unlock cache did not warm");later(2,()->pollUnlock(left-1));return;}check(value&&quests.unlocked(T,"sanitation_reform"),"legacy quest API exposes both preserved chain and acknowledged cooperative unlocks");cancelCase();}
    void cancelCase()throws Exception{
        menu.command(mayor,new String[]{"plan","native_city"});String city="native_city_"+T.toString().replace("-","");await(api.cooperativeProject(city),row->in(()->{check(row.get("ownerTown").equals(T.toString()),"actual mayor command scopes city project to authenticated current town");material(id("delivery-cancel"),T,M,"OAK_LOG",64,city,()->{menu.command(Bukkit.getConsoleSender(),new String[]{"cancel",city,"confirm","Build cancelled by native test"});await(api.balances(),b->in(()->{check(b.get("OAK_LOG")==116L,"cancel returns paid reservation to server pool without a player refund");await(api.cooperativeUnlocks(T),keys->in(()->{check(!keys.contains("joint_native_city"),"cancelled project grants no completion unlock");check(Arrays.equals(Files.readAllBytes(proof.resolve("chain.yml")),Files.readAllBytes(plugin.getDataFolder().toPath().resolve("quests-data.yml"))),"cooperative ledger never rewrites original completed chains");providerFailure();}));}));});}));
    }
    void expectFailure(CompletionStage<?> job,String why,Work next){job.whenComplete((value,error)->{if(error==null){fail(new AssertionError(why));return;}later(1,()->{check(true,why);next.run();});});}
    void providerFailure()throws Exception{
        var owner=Bukkit.getPluginManager().getPlugin("NeverLandTownyContracts");
        SuiteState.freeze(owner.getName());denied(()->quests.unlocked(T,"joint_native_common"),"frozen Contracts blocks cached cooperative authorization");check(quests.unlocked(T,"sanitation_reform"),"frozen optional supplier preserves legacy chain result");SuiteState.thaw(owner.getName());
        Bukkit.getServicesManager().unregister(ServerMaterialsApi.class,api);denied(()->quests.unlocked(T,"joint_native_common"),"missing materials service reports unknown even with a warm unlock cache");Bukkit.getServicesManager().register(ServerMaterialsApi.class,api,owner,org.bukkit.plugin.ServicePriority.Normal);
        var fault=ServerMaterials.class.getDeclaredField("fault");fault.setAccessible(true);fault.setBoolean(ledger,true);denied(()->quests.unlocked(T,"joint_native_common"),"failed ledger reports unknown even with warm cooperative cache");
        expectFailure(coop.plan(coop.templates().get("native_common"),null,"NativeCheck"),"failed ledger refuses new project mutation",()->{fault.setBoolean(ledger,false);check(quests.unlocked(T,"sanitation_reform"),"failed optional ledger leaves old completed chain intact");check(plugin.isEnabled()&&!SuiteState.frozen(plugin.getName()),"optional service failure never disables or freezes Quests");Files.copy(config,proof.resolve("cooperative.yml"));var bad=org.bukkit.configuration.file.YamlConfiguration.loadConfiguration(config.toFile());bad.set("enabled","BROKEN_VALUE");bad.save(config.toFile());finishPhase();});
    }
    void verifyAuditThenResume(){
        var evidence=new CompletableFuture<Set<String>>();Bukkit.getAsyncScheduler().runNow(this,task->{try{var rows=new HashSet<String>();AuditJournal.scan(plugin.getDataFolder().toPath().resolve("audit"),r->{if(r.kind().equals("CITY_PROJECT")&&r.details().startsWith("Общая стройка:"))rows.add(r.operation()+"/"+r.outcome());});evidence.complete(Set.copyOf(rows));}catch(Throwable error){evidence.completeExceptionally(error);}});
        await(evidence,rows->in(()->{String city="native_city_"+T.toString().replace("-","");check(rows.equals(Set.of("native_common/PLAN","native_common/COMPLETED",city+"/PLAN",city+"/CANCELLED")),"all four administrative audit receipts survive shutdown and are unique");resumeCooperative();}));
    }
    void resumeCooperative()throws Exception{
        check(quests.unlocked(T,"sanitation_reform"),"full restart keeps old city-chain result");check(Arrays.equals(Files.readAllBytes(proof.resolve("chain.yml")),Files.readAllBytes(plugin.getDataFolder().toPath().resolve("quests-data.yml"))),"optional cooperative configuration cannot rewrite old chain data");
        await(api.cooperativeProject("native_common"),row->in(()->{check(row.get("state").equals("COMPLETED")&&row.get("credited").equals(Map.of("OAK_LOG",128L,"GLASS",64L)),"full restart preserves completed exact budget and city contributions");await(api.balances(),balance->in(()->{check(balance.get("OAK_LOG")==116L&&balance.get("GLASS")==0L,"restart neither respends nor duplicates returned goods");await(api.cooperativeHistory("native_common"),history->in(()->{check(history.size()==2,"plan and completed actions remain unique after restart");
            if(phase.equals("broken")){check(!coop.issue().isEmpty(),"invalid optional settings suspend only cooperative UI");denied(()->quests.unlocked(T,"joint_native_common"),"unavailable optional unlock reports unknown rather than revoking persisted benefits");Files.write(config,Files.readAllBytes(proof.resolve("cooperative.yml")));finishPhase();}
            else{check(coop.issue().isEmpty(),"repaired optional config restores same cooperative ledger");pollResume(40);}
        }));}));}));
    }
    void pollResume(int left)throws Exception{boolean ok=false;try{ok=quests.unlocked(T,"joint_native_common");}catch(IllegalStateException pending){}if(!ok){if(left<=0)throw new AssertionError("restored unlock not ready");later(2,()->pollResume(left-1));return;}check(ok,"repaired restart acknowledges cooperative result without new money or materials");finishPhase();}
    void capture(String label)throws Exception{
        Path folder=proof.resolve(phase+"-"+label);Files.createDirectories(folder);Path db=(Path)field(ledger,"file");var result=new StringBuilder();for(String suffix:List.of("","-wal","-shm")){Path file=Path.of(db+suffix);if(Files.exists(file)){byte[] bytes=Files.readAllBytes(file);Files.write(folder.resolve(file.getFileName()),bytes);result.append(file.getFileName()).append(" size=").append(bytes.length).append(" sha256=").append(HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(bytes))).append('\n');}}Files.writeString(folder.resolve("files.txt"),result.toString());
    }
    void finishPhase()throws Exception{
        if(Files.exists(Path.of("FAST_NATIVE_STOP"))){shutdownPhase();return;}
        var ready=new CompletableFuture<Void>();((java.util.concurrent.ExecutorService)field(ledger,"worker")).execute(()->{try{var connection=(java.sql.Connection)field(ledger,"connection");var values=new StringBuilder("autoCommit="+connection.getAutoCommit()+"\n");for(String sql:List.of("PRAGMA database_list","PRAGMA journal_mode","PRAGMA synchronous","SELECT material,received,available FROM balances","SELECT id,state FROM cooperative_projects")){values.append(sql).append('\n');try(var stmt=connection.createStatement();var rows=stmt.executeQuery(sql)){while(rows.next()){for(int i=1;i<=rows.getMetaData().getColumnCount();i++)values.append(rows.getObject(i)).append(" | ");values.append('\n');}}}Files.writeString(proof.resolve(phase+"-before-close-sql.txt"),values);capture("before-close");ledger.closed().whenComplete((value,error)->{try{capture("after-close");}catch(Exception bad){getLogger().log(java.util.logging.Level.SEVERE,"Cannot capture closed ledger",bad);}});ready.complete(null);}catch(Throwable error){ready.completeExceptionally(error);}});await(ready,ignored->in(this::shutdownPhase));
    }
    void shutdownPhase()throws Exception{TownyUniverse.getInstance().getDataSource().saveAll();Files.writeString(proof.resolve(phase+"-passed.txt"),"PASS "+checks+" assertions; actual Folia Towny Contracts Quests Control services, registered API, commands, inventories, SQLite transactions and three JVM boots. Explicit offline Player/InventoryView/scheduler substitutes and inventory-confirmed delivery fixtures; no client rendering or real bank payment claimed.\n");Bukkit.getGlobalRegionScheduler().run(this,t->Bukkit.shutdown());}
